/** Returns the AI-resistance score 0-100. Defaults to 50 when unknown. */
export function getAiResistance(skill: string): number {
  return AI_RESISTANCE[skill] ?? 50;
}

export function isAiProof(skill: string): boolean {
  return getAiResistance(skill) >= 70;
}

export function isAtRisk(skill: string): boolean {
  return getAiResistance(skill) <= 30;
}
